package com.smartdairy.controller;
import com.smartdairy.entity.Supplier; import com.smartdairy.service.SupplierService; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException;
public class SupplierUpdateServlet extends HttpServlet {private final SupplierService service=new SupplierService(); protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{Supplier s=new Supplier();s.setId(Integer.parseInt(req.getParameter("id")));s.setName(req.getParameter("name"));s.setMobile(req.getParameter("mobile"));s.setAddress(req.getParameter("address"));s.setAnimalType(req.getParameter("animal_type"));s.setBankDetails(req.getParameter("bank_details"));s.setStatus(req.getParameter("status"));service.update(s);resp.sendRedirect("supplier.jsp?updated=true");}catch(Exception e){resp.sendRedirect("supplier.jsp?error="+java.net.URLEncoder.encode(e.getMessage(),"UTF-8"));}}}
